import { MovieCardProps } from './MovieCard/MovieCard';
import React, { useState, useEffect, createContext } from 'react';


export const DataContext = createContext({
  moviesData: [] as MovieCardProps[],
  loading: true,
  error: null as string | null,
});

export const DataProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [moviesData, setMoviesData] = useState<MovieCardProps[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  const fetchData = async () => {
    try {
      const response = await fetch('/public/database.json'); // Ścieżka do lokalnego pliku
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      console.log(data);
      // setMoviesData(data.moviesList);
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  // Fetch data from the local file
  useEffect(() => {
    fetchData();
  }, []);

  return <DataContext.Provider value={{ moviesData, loading, error }}>{children}</DataContext.Provider>;
};
